import 'package:flutter/material.dart';
class DoctorScheduleScreen extends StatefulWidget{const DoctorScheduleScreen({super.key});@override State<DoctorScheduleScreen> createState()=>_DoctorScheduleScreenState();}
class _DoctorScheduleScreenState extends State<DoctorScheduleScreen>{final days=<String,bool>{'Monday':true,'Tuesday':true,'Wednesday':true,'Thursday':true,'Friday':true,'Saturday':true,'Sunday':false};@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Working schedule')),body:ListView(padding:const EdgeInsets.all(18),children:[...days.entries.map((entry)=>SwitchListTile(value:entry.value,title:Text(entry.key),subtitle:Text(entry.value?'10:00 AM–1:00 PM • 5:00 PM–8:00 PM':'Unavailable'),onChanged:(value)=>setState(()=>days[entry.key]=value))),const SizedBox(height:14),DropdownButtonFormField<int>(value:30,items:[15,20,30,45,60].map((x)=>DropdownMenuItem(value:x,child:Text('$x minutes'))).toList(),onChanged:null,decoration:const InputDecoration(labelText:'Slot duration')),const SizedBox(height:18),FilledButton(onPressed:(){},child:const Text('Save schedule'))]));}
